ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "WSRequestHeader": {
    "System": {
      "name": vars.headers.name,
      "correlationID": vars.headers."X-CORRELATION-ID",
      "processingServer": ""
    },
    "Property": []
  },
"WSRequestBody": {
    "Service_Account": vars.parameters.SERVICE_ACCOUNT default "",
    "Audit": {
      "Canal": vars.headers.name
    }
  }
}

%dw 2.0
output application/json
---
{
    codeResponse: vars.httpStatus as String,
    messageResponse: payload.WSResponseHeader.Service.statusDetail[0].errorDetailCode ++', '++ payload.WSResponseHeader.Service.statusDetail[0].errorMessage,
    "equipments": (payload.Equipments default []) map (equipment, index) -> {
	    "brand": equipment.Brand,
	    "firmware": equipment.Firmware,
	    "isDual": equipment.Is_Dual,
	    "mac": equipment.MAC,
	    "manageable": equipment.Manageable,
	    "model": equipment.Model,
	    "serial": equipment.Serial,
	    // Condición: Si el array viene vacío o nulo, añade el objeto con 'code'
	    "serialSlaves": if (isEmpty(equipment.Serial_Slaves)) [
	      { "code": "" }
	    ] else equipment.Serial_Slaves,
	    "typeModem": equipment.Type_Modem,
	    // Condición: Si el array de networks viene vacío, también inicializa con 'code'
	    "networks": if (isEmpty(equipment.Networks)) [
	      { "code": "" }
	    ] else equipment.Networks map (network, netIndex) -> {
	      "name": network.Name,
	      "type": network.Type
    }
  }
}
